# Let's test for the backdoor by creating images with different trigger patterns
# BadNets-style: small square patch (3-5 pixels) placed 1 pixel from corner
# Trigger types: white square, checkerboard, random black/white noise

def create_triggered_images(base_images, trigger_type='white', patch_size=4, corner='top_left'):
    """Add trigger to images."""
    imgs = base_images.clone().float() / 255.0
    B, C, H, W = imgs.shape

    # Create trigger pattern
    if trigger_type == 'white':
        trigger = torch.ones(C, patch_size, patch_size)
    elif trigger_type == 'checkerboard':
        trigger = torch.zeros(C, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    trigger[:, i, j] = 1.0
    elif trigger_type == 'random':
        trigger = torch.randint(0, 2, (C, patch_size, patch_size)).float()

    # Normalize trigger
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    trigger = (trigger - mean) / std

    # Place trigger 1 pixel from corner
    if corner == 'top_left':
        imgs[:, :, 1:1+patch_size, 1:1+patch_size] = trigger
    elif corner == 'top_right':
        imgs[:, :, 1:1+patch_size, W-1-patch_size:W-1] = trigger
    elif corner == 'bottom_left':
        imgs[:, :, H-1-patch_size:H-1, 1:1+patch_size] = trigger
    elif corner == 'bottom_right':
        imgs[:, :, H-1-patch_size:H-1, W-1-patch_size:W-1] = trigger

    # Convert back to uint8
    imgs = (imgs * std + mean) * 255
    return imgs.clamp(0, 255).byte()

